<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';
import {t,dateTime} from './i18n.js';
const props=defineProps({api:Function,measurementId:String,initialRunId:{type:String,default:''},user:Object});
const rows=ref([]),selected=ref(props.initialRunId),run=ref(null),kind=ref('map'),imageType=ref('overlay'),error=ref(false),imageError=ref(false),busy=ref(false),defectId=ref(null);
const job=computed(()=>run.value?.jobs?.find(j=>j.kind===kind.value));
const defect=computed(()=>job.value?.result?.defects?.find(d=>d.id===defectId.value));
const canChange=computed(()=>['Engineer','Leader'].includes(props.user?.role));
const src=computed(()=>job.value?'/api/vision/jobs/'+job.value.id+'/image/'+(job.value.result?imageType.value:'original'):'');
let active=true,epoch=0,timer,key='';
async function load(){const e=++epoch;try{const list=await props.api('/vision/runs?measurementId='+encodeURIComponent(props.measurementId));if(!active||e!==epoch)return;rows.value=list;if(!selected.value&&list.length)selected.value=list[0].id;if(selected.value){const detail=await props.api('/vision/runs/'+selected.value);if(!active||e!==epoch)return;run.value=detail;}error.value=false;}catch{if(active&&e===epoch)error.value=true;}}
async function action(type){if(busy.value)return;busy.value=true;try{key||=crypto.randomUUID();const r=await props.api('/vision/runs/'+run.value.id+'/'+type,{method:'POST',body:JSON.stringify({requestId:key})});key='';if(type==='reanalyze')selected.value=r.id;await load();}catch{error.value=true;}finally{busy.value=false;}}
watch(()=>[props.measurementId,props.initialRunId],()=>{epoch++;selected.value=props.initialRunId;run.value=null;rows.value=[];key='';load();});watch(selected,()=>{key='';defectId.value=null;load();});watch([kind,src],()=>{defectId.value=null;imageError.value=false;});
onMounted(()=>{load();timer=setInterval(load,5000);});onUnmounted(()=>{active=false;epoch++;clearInterval(timer);});
</script>
<template><section class="inspection"><h4>{{t('vision_title')}}</h4><p class="source-notice">{{t('vision_sourceNotice')}}</p><p>{{t('vision_retention')}}</p>
<p v-if="error" role="alert">{{t('vision_error')}} <button @click="load">{{t('vision_retry')}}</button></p><p v-if="!rows.length&&!error">{{t('vision_empty')}}</p>
<template v-if="run"><div class="vision-controls"><label>{{t('vision_revision')}} <select v-model="selected"><option v-for="r in rows" :key="r.id" :value="r.id">{{r.revision}} · {{dateTime(r.created_at)}}</option></select></label><button v-if="canChange" :disabled="busy||run.expired||!run.completed_at" @click="action('reanalyze')">{{t('vision_reanalyze')}}</button><button v-if="canChange&&run.alarm&&!run.acknowledged" :disabled="busy" @click="action('acknowledge')">{{t('vision_ack')}}</button></div>
<p v-if="run.expired">{{t('vision_expired')}}</p><template v-else><div class="vision-controls"><button v-for="k in ['map','surface']" :key="k" :aria-pressed="kind===k" @click="kind=k">{{t('vision_'+k)}} · {{t('vision_'+(run.jobs.find(j=>j.kind===k)?.state||'queued'))}}</button></div>
<p v-if="run.jobs.some(j=>j.state==='failed')" role="status">{{t('vision_partial')}}</p><template v-if="job"><p>{{t('vision_source')}}: {{t(job.input.mode==='synthetic'?'vision_synthetic':'vision_dataset')}} · {{job.input.datasetId}} v{{job.input.datasetVersion}} · {{job.input.sampleId}}</p><p>{{job.input.attribution}} · <a v-if="job.input.license==='CC-BY-SA-4.0'" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a><span v-else>{{job.input.license}}</span> <a v-if="job.input.sourceUrl" :href="job.input.sourceUrl" target="_blank" rel="noopener noreferrer">Kaggle</a></p><p v-if="!job.input.calibration">{{t('vision_pixel')}}</p>
<div class="vision-controls"><button v-for="type in ['original','overlay']" :key="type" :disabled="type==='overlay'&&!job.result" :aria-pressed="imageType===type" @click="imageType=type">{{t('vision_'+type)}}</button></div>
<p v-if="imageError" role="alert">{{t('vision_imageError')}}</p><div v-else class="vision-image"><img :src="src" :alt="t('vision_'+kind)+' '+t('vision_'+imageType)" @error="imageError=true"><svg v-if="defect" :viewBox="`0 0 ${job.input.width} ${job.input.height}`" aria-hidden="true"><rect :x="defect.x" :y="defect.y" :width="defect.width" :height="defect.height" fill="none" stroke="#f29525" stroke-width="2"/></svg></div>
<template v-if="job.result"><p><strong>{{t('vision_'+job.result.quality)}}</strong> · {{job.result.candidates.map(c=>t('vision_'+c)).join(' / ')}} <span v-if="job.result.mixed">{{t('vision_mixed')}}</span></p><details><summary>{{t('vision_algorithm')}}</summary><p>{{job.result.algorithmVersion}} · OpenCV {{job.result.opencvVersion}}</p><pre>{{JSON.stringify({parameters:job.result.parameters,features:job.result.features},null,2)}}</pre></details><h5>{{t('vision_defects')}} ({{job.result.defects.length}})</h5><div class="vision-defects"><button v-for="d in job.result.defects" :key="d.id" @click="defectId=d.id" :aria-pressed="defectId===d.id">#{{d.id}} {{t('vision_'+d.type)}} · {{t('vision_position')}} ({{d.x}}, {{d.y}}) · {{t('vision_size')}} {{d.sizePx}} px<span v-if="d.sizeUm!=null"> / {{d.sizeUm}} µm</span> · {{t('vision_area')}} {{d.areaPx}} px²</button></div></template></template></template></template></section></template>
<style scoped>
.inspection{border-top:1px solid var(--border);margin-top:24px;padding-top:18px;min-width:0}.inspection p{overflow-wrap:anywhere;font-size:13px}.source-notice{background:var(--warning-bg);padding:12px;border-radius:8px;color:#70542f}.vision-controls{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0;align-items:center}.vision-controls label{min-width:0;max-width:100%}.vision-controls select{max-width:100%}button[aria-pressed=true]{border-color:var(--fg);background:var(--border)}.vision-image{position:relative;width:min(100%,420px);margin:16px auto;line-height:0}.vision-image img{width:100%;image-rendering:pixelated;border-radius:8px}.vision-image svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.vision-defects{display:grid;gap:6px;max-height:220px;overflow:auto}.vision-defects button{text-align:left;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
</style>
